# ---------- portal URL check ----------

def on_check_url(self):
    # Validates the URL and starts ONE low-impact GET to the exact URL
    # in the "Portal URL" field (no crawl, no retries, no credentials)
    # in a background thread so the window stays responsive.
    if self.checking:
        return
    url = self.url_entry.get().strip()
    try:
        parts = urllib.parse.urlsplit(url)
    except ValueError:
        parts = None
    if parts is None or parts.scheme not in ("http", "https") or not parts.netloc:
        self.log_line("Enter a valid portal URL, e.g. http://example.com:8080", "error")
        return
    self.checking = True
    self.check_button.config(state="disabled")
    self.check_label.config(text="checking…", foreground="#555")
    self.log_line(f"Checking URL: {url} (one request, {CHECK_TIMEOUT} s timeout)…", "info")
    threading.Thread(target=self._url_check_worker, args=(url,), daemon=True).start()

def _url_check_worker(self, url):
    start = time.monotonic()
    ok = False
    try:
        with urllib.request.urlopen(url, timeout=CHECK_TIMEOUT,
                                     headers={"User-Agent": "macstalker-gui/1.0"}) as resp:
            ok = True
            text = f"reachable — HTTP {resp.status} in {time.monotonic() - start:.2f} s"
            if resp.geturl() != url:
                text += f" (redirected to {resp.geturl()})"
    except urllib.error.HTTPError as exc:
        # The server answered; the status code is still a useful result.
        text = f"reachable, but HTTP {exc.code} in {time.monotonic() - start:.2f} s"
    except urllib.error.URLError as exc:
        text = (f"no response within {CHECK_TIMEOUT} s (timeout)"
                if isinstance(exc.reason, socket.timeout)
                else f"unreachable ({exc.reason})")
    except Exception as exc:
        text = f"check failed ({exc})"
    if not self._destroyed:
        self.queue.put(("check_done", (ok, text)))

