def _handle_event(self, item):
    kind, text = item
    if kind == "progress":
        self.status_label.config(text=f"{self.mac_count} found — {text}")
    elif kind == "check_done":
        self._handle_check_done(text)
    else:
        self.log_line(text, kind)
        if kind == "found":
            self.status_label.config(text=f"{self.mac_count} found")

def _handle_check_done(self, result):
    ok, message = result
    self.checking = False
    self.check_button.config(state="normal")
    self.check_label.config(text=message, foreground="" if ok else "#e06c75")
    self.log_line(("Portal check OK: " if ok else "Portal check failed: ") + message,
                  "found" if ok else "error")
